#!/usr/bin/env bash
# MongoDB user per service for the local/ephemeral runtime. For every mongodb
# row of services.tsv (postgresql rows are postgres/init's): a user named by
# the row's app_role, created in the row's database with readWrite on that
# database only (credential from the env var named in the row, generated by
# compose/scripts/init-env.sh), so a service's MONGODB_URI
# (mongodb://<user>:<credential>@mongo:27017/<database>) authenticates against
# its own database and is refused on every other. Re-runnable: an existing user
# gets its credential and roles set again (service-user.js).
#
# Runs as the mongo-init one-shot (same image as mongo, after mongo is healthy)
# rather than as a docker-entrypoint-initdb.d script: the image's first-start
# init runs a temporary mongod on 127.0.0.1 only, and a service could connect
# between that and the user creation. Credentials reach mongosh through the
# environment only, never its command line.
#
# Environment: FBX_SERVICES_TSV (default /fbx/services.tsv), FBX_MONGO_URI
# (default mongodb://mongo:27017/admin), MONGO_ROOT_USER, MONGO_ROOT_CRED and
# the credential variable of each mongodb row.
set -euo pipefail

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
services="${FBX_SERVICES_TSV:-/fbx/services.tsv}"
uri="${FBX_MONGO_URI:-mongodb://mongo:27017/admin}"
: "${MONGO_ROOT_USER:?MONGO_ROOT_USER is not set}" "${MONGO_ROOT_CRED:?MONGO_ROOT_CRED is not set (run compose/fbx-local.sh init)}"
export MONGO_ROOT_USER MONGO_ROOT_CRED

attempts="${FBX_MONGO_WAIT_ATTEMPTS:-60}"
for ((i = 1; ; i++)); do
  mongosh --quiet "$uri" --eval 'db.runCommand({ ping: 1 }).ok' >/dev/null 2>&1 && break
  [ "$i" -lt "$attempts" ] || { echo "[mongo-init] MongoDB at $uri did not answer" >&2; exit 1; }
  sleep 2
done

n=0
while IFS=$'\t' read -r key service_id _ database _ user cred_var _ _ store _; do
  [[ -z "$key" || "$key" == \#* ]] && continue
  case "$store" in
    mongodb) ;;
    postgresql) continue ;;
    *) echo "[mongo-init] $key: unknown store '$store' in services.tsv (postgresql or mongodb)" >&2; exit 1 ;;
  esac
  cred="${!cred_var:-}"
  [ -n "$cred" ] || { echo "[mongo-init] $cred_var is not set for $key" >&2; exit 1; }
  echo "[mongo-init] $service_id: database $database, user $user (readWrite on $database only)"
  FBX_DB="$database" FBX_USER="$user" FBX_CRED="$cred" mongosh --quiet "$uri" --file "$here/service-user.js"
  n=$((n + 1))
done < "$services"
echo "[mongo-init] done ($n MongoDB service user(s))"
